import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:hive/hive.dart';
import 'enums.dart';

part 'user_preference_analysis.freezed.dart';
part 'user_preference_analysis.g.dart';

/// Represents the analysis of user preferences from their travel description
/// This is generated by LLM analysis of the user's natural language input
@freezed
@HiveType(typeId: 13)
class UserPreferenceAnalysis with _$UserPreferenceAnalysis {
  const factory UserPreferenceAnalysis({
    @HiveField(0) required String primaryFocus,
    @HiveField(1) required TravelPace travelPace,
    @HiveField(2) required List<String> interests,
    @HiveField(3) required List<String> avoidances,
    @HiveField(4) required String mood,
    @HiveField(5) required List<String> keywords,
    @HiveField(6) @Default([]) List<String> detectedInterests,
  }) = _UserPreferenceAnalysis;

  factory UserPreferenceAnalysis.fromJson(Map<String, dynamic> json) =>
      _$UserPreferenceAnalysisFromJson(json);
}

/// Represents basic user preferences for trip planning
@freezed
@HiveType(typeId: 14)
class BasicPreferences with _$BasicPreferences {
  const factory BasicPreferences({
    @HiveField(0) required BudgetRange budget,
    @HiveField(1) required int groupSize,
    @HiveField(2) required TravelStyle travelStyle,
  }) = _BasicPreferences;

  factory BasicPreferences.fromJson(Map<String, dynamic> json) =>
      _$BasicPreferencesFromJson(json);
}